const incoming = $('Normalize WAHA Payload').item.json;
const row = $json || {};
return {
  json: {
    contact: incoming['Контакты'],
    supplier_message: incoming.supplier_message,
    has_media: incoming.has_media,
    media_url: incoming.media_url || '',
    file_name: incoming.file_name || '',
    mime_type: incoming.mime_type || '',
    session: incoming.session || 'default',
    current_stage: row['Stage'] || 'new',
    known_company_name: row['Название компании временно'] || '',
    known_activity: row['Деятельность компании временно'] || '',
    known_catalog: row['Ссылка на каталог временно'] || '',
    package_done: row['Полный пакет получен'] || '',
    first_contact_sent: row['First Contact Sent'] || '',
    status_chat: row['Статус'] || ''
  }
};

const incoming = $('Normalize Telegram payload').item.json;
const raw = String($json.buffer_state || '').trim();
let row = {};
if (raw) {
  try {
    row = JSON.parse(raw);
  } catch (e) {
    row = {};
  }
}
const existingBuffer = String(row.Buffer || '').trim();
const currentPart = String(incoming.message_text || '').trim();
const mergedBuffer = [existingBuffer, currentPart].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
const state = {
  'Chat ID': incoming.chat_id,
  'Buffer': mergedBuffer,
  'Pending Token': incoming.pending_token,
  'Last Message At': incoming.timestamp,
  'Sender Name': incoming.sender_name,
  'Username': incoming.username,
  'Last Reply': row['Last Reply'] || '',
  'Updated At': $now
};
return {
  json: {
    ...state,
    redis_key: `tg_buffer:${incoming.chat_id}`,
    redis_value: JSON.stringify(state)
  }
};

let row = {};
try {
  row = JSON.parse(String($json.buffer_state || '{}'));
} catch (e) {
  row = {};
}
return {
  json: {
    chat_id: row['Chat ID'] || '',
    merged_message: row['Buffer'] || '',
    sender_name: row['Sender Name'] || '',
    username: row['Username'] || '',
    pending_token: row['Pending Token'] || '',
    last_message_at: row['Last Message At'] || '',
    last_reply: row['Last Reply'] || '',
    redis_key: $('Build buffer update').item.json.redis_key
  }
};

